# resume-picker.ps1 - interactive session picker for bare `claude -r` (PowerShell twin)
# Called by the resume shim (resume-shim.ps1) when -r/--resume is present with NO
# session id. Plain Claude Code's own picker would resume a Lumo session under a model
# it does not know ("Session model lumo-max could not be restored"), and by the time
# its picker runs it is too late to reroute. This helper lists recent transcripts first
# so the right launcher (claude-lumo vs the real claude) can be chosen.
# Do not edit this file: it belongs to the claude-lumo repo and updates overwrite it.
#
# Usage: powershell -NoProfile -File resume-picker.ps1 <original claude args...>
#   - Lists the 15 most recent transcripts (by mtime) across the same stores and in
#     the same order the shim uses, showing engine (lumo/claude), last-modified time,
#     project folder basename and the short id (first 8 chars).
#   - A number resumes that session with the matching engine: the bare -r/--resume
#     flag is replaced by "--resume <full-id>" and every other argument is kept in order.
#   - "p" opens plain Claude Code's own picker (the behavior without this helper).
#     Empty or invalid input also falls through to the real claude with the ORIGINAL
#     arguments unchanged. Fail-open: the helper never traps the user. Same for
#     redirected stdin and empty transcript stores.
#   - RESUME_PICKER_FORCE_MENU=1 forces the menu even with redirected stdin, so the
#     test harness can drive the interactive path.
#
# Transcript search order (same as resume-shim.ps1):
#   1. $env:CLAUDE_CONFIG_DIR if set
#   2. ~/.claude (shared mode)
#   3. ~/.claude-lumo/config (the separated Lumo data store, when data separation is on)

# No param() block: with "powershell -File resume-picker.ps1 -r --strict" the raw
# tokens must reach $args as strings; a declared parameter would try to bind "-r".

function Invoke-PlainClaude {
    # Run the real claude with the original arguments (bypassing the shim function).
    # Callers must NOT wrap this in exit (...) or $x = ...: the child's stdout would
    # be captured as this function's return value instead of reaching the console.
    # $LASTEXITCODE carries the child's exit code back to the caller.
    param([string[]]$OriginalArgs)
    $exe = (Get-Command claude -CommandType Application -ErrorAction Stop | Select-Object -First 1).Source
    & $exe @OriginalArgs
}

# Run the real claude with the original arguments (bypassing the shim function);
# propagate its exit code. See Invoke-PlainClaude for why this is a statement, not
# exit (...).
function Invoke-PlainClaudeThenExit {
    Invoke-PlainClaude $origArgs
    exit $LASTEXITCODE
}

$origArgs = @()
if ($args) { $origArgs = @($args | ForEach-Object { [string]$_ }) }

# Non-interactive (stdin redirected): behave exactly like the old shim - plain claude,
# original args - so scripts and pipelines are never stalled on a menu.
if ([Console]::IsInputRedirected -and $env:RESUME_PICKER_FORCE_MENU -ne '1') {
    Invoke-PlainClaudeThenExit
}

# Scan the transcript stores in the shim's order; keep the 15 most recent by mtime.
# $env:HOME mirrors the bash twin ($HOME is an env var there); PowerShell's automatic
# $HOME ignores it, which would scan the real profile even when HOME is overridden.
$homeDir = $HOME
if ($env:HOME) { $homeDir = $env:HOME }
$stateDir = if ($env:CLAUDE_LUMO_STATE_DIR) { $env:CLAUDE_LUMO_STATE_DIR } else { "$homeDir\.claude-lumo" }
$dirs = @("$homeDir\.claude", "$stateDir\config")
if ($env:CLAUDE_CONFIG_DIR) { $dirs = @($env:CLAUDE_CONFIG_DIR) + $dirs }

$rows = @()
foreach ($d in ($dirs | Select-Object -Unique)) {
    $items = Get-ChildItem -Path "$d\projects\*\*.jsonl" -File -ErrorAction SilentlyContinue
    foreach ($t in $items) {
        $eng = 'claude'
        if (Select-String -Path $t.FullName -SimpleMatch '"model":"lumo-' -List -Quiet) { $eng = 'lumo' }
        $rows += [pscustomobject]@{ Time = $t.LastWriteTime; Engine = $eng; Path = $t.FullName }
    }
}
$sessions = @($rows | Sort-Object Time -Descending | Select-Object -First 15)

# No transcripts anywhere -> plain claude, original args.
if ($sessions.Count -eq 0) {
    Invoke-PlainClaudeThenExit
}

# Print the menu.
for ($i = 0; $i -lt $sessions.Count; $i++) {
    $s = $sessions[$i]
    $project = Split-Path -Leaf (Split-Path -Parent $s.Path)
    $shortId = [IO.Path]::GetFileNameWithoutExtension($s.Path).Substring(0, [Math]::Min(8, [IO.Path]::GetFileNameWithoutExtension($s.Path).Length))
    '{0,2}) [{1}] {2,-16} {3}  {4}' -f ($i + 1), $s.Engine, $s.Time.ToString('yyyy-MM-dd HH:mm'), $project, $shortId | Write-Host
}
"  p) plain Claude Code's own picker" | Write-Host
$choice = Read-Host 'Choice (number, p, or Enter for plain claude)'

if ($choice -eq 'p') {
    Invoke-PlainClaudeThenExit
}

$num = 0
$picked = $null
if ([int]::TryParse($choice, [ref]$num) -and $num -ge 1 -and $num -le $sessions.Count) {
    $picked = $sessions[$num - 1]
}
if (-not $picked) {
    # Empty or invalid input: fail open, original arguments unchanged.
    Invoke-PlainClaudeThenExit
}

$fullId = [IO.Path]::GetFileNameWithoutExtension($picked.Path)

# Rebuild the arguments: same order minus the bare -r/--resume token.
# Tokens after "--" are end-of-options: a literal -r/--resume there is a
# positional argument and must be kept (same end-of-options logic as the shim).
$newArgs = @()
$endOpts = $false
foreach ($a in $origArgs) {
    if ($endOpts) { $newArgs += [string]$a; continue }
    if ($a -eq '--') { $endOpts = $true; $newArgs += '--'; continue }
    if ($a -ne '-r' -and $a -ne '--resume') { $newArgs += [string]$a }
}

if ($picked.Engine -eq 'lumo') {
    & claude-lumo --resume $fullId @newArgs
    exit $LASTEXITCODE
} else {
    $exe = (Get-Command claude -CommandType Application -ErrorAction Stop | Select-Object -First 1).Source
    & $exe --resume $fullId @newArgs
    exit $LASTEXITCODE
}
